(function (w) {
  let timer;
  function init(){const panel=document.getElementById('searchPanel');if(!panel)return;const input=panel.querySelector('input');const results=panel.querySelector('[data-search-results]');const view=panel.querySelector('[data-search-view]');function close(){w.Bookivo.Modal.close(panel);}document.addEventListener('click',e=>{if(e.target.closest('[data-search-open]')){w.Bookivo.Modal.open(panel);input.focus();}if(e.target.closest('[data-search-close]'))close();});input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(view)view.href='books.html?q='+encodeURIComponent(q);if(!q){results.innerHTML='<p class="search-hint">Search titles, authors, categories or topics.</p>';return;}results.innerHTML=w.Bookivo.Skeleton.grid(3);timer=setTimeout(async()=>{const books=await w.Bookivo.Api.books.search(q);results.innerHTML=books.length?w.Bookivo.BookCard.renderGrid(books):'<p class="search-hint">No books found. Try another search.</p>';},220);});panel.querySelector('form').addEventListener('submit',e=>{e.preventDefault();w.location.href='books.html?q='+encodeURIComponent(input.value.trim());});panel.querySelectorAll('[data-search-chip]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.searchChip;input.dispatchEvent(new Event('input'));}));}
  w.Bookivo.Search={init};
})(window);
;
// js/components/product-offer.js
(function(B){
 B.ProductOffer={bind(book,anchor,price){
  if(!anchor||!price)return;
  const offers=(window.bookivoSettings?.offers||[]).filter(o=>o.show_product && o.code!=='PARTNER_PATTERN' && (!o.book_ids||o.book_ids.includes(book.id)));
  const ranked=offers.map(o=>({offer:o,result:B.Pricing.calculateOrder({items:[book],mode:'coupon',couponCode:o.code,nowIST:new Date()})})).filter(x=>x.result.discountTotal>0).sort((a,b)=>b.result.discountTotal-a.result.discountTotal);
  if(!ranked.length)return;const {offer}=ranked[0];
  const line=document.createElement('p');line.className='product-offer';
  const label=document.createElement('span');label.textContent='You have a coupon: '+offer.code+' ';const btn=document.createElement('button');btn.type='button';btn.textContent='APPLY NOW';line.append(label,btn);anchor.after(line);
  btn.onclick=async()=>{btn.disabled=true;try{const checked=await B.Api.coupons.validate(offer.code,[book]);if(!checked.valid){B.Toast.show(checked.message,'error');return;}const result=B.Pricing.calculateOrder({items:[book],mode:'coupon',couponCode:offer.code,nowIST:new Date()});sessionStorage.setItem('bv_selected_coupon',offer.code);price.replaceChildren();const total=document.createElement('strong');total.textContent=B.Format.rupees(result.total);const before=document.createElement('del');before.textContent=B.Format.rupees(book.price);price.append(total,' ',before);const sticky=document.querySelector('[data-sticky-buy] strong');if(sticky)sticky.textContent=B.Format.rupees(result.total);label.textContent=offer.code+' applied. Save '+B.Format.rupees(result.discountTotal)+' at checkout. ';btn.textContent='APPLIED';btn.disabled=true;const buy=document.querySelector('#buyNowBtn');if(buy)buy.textContent='Buy Now · '+B.Format.rupees(result.total);B.Toast.show('Coupon applied successfully.','success');}catch(e){B.Toast.show(e.message,'error');}finally{btn.disabled=btn.textContent==='APPLIED';}};
 }};
 B.Download={async start(book,button){const old=button.textContent;button.disabled=true;button.textContent='Preparing download…';try{const r=await fetch(book.fileUrl);if(!r.ok)throw Error('Download unavailable. Please retry.');const blob=await r.blob();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BOOKIVO-AI-Toolkit.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){B.Toast.show(e.message||'Download failed. Please retry.','error');}finally{button.disabled=false;button.textContent=old;}}};
})(window.Bookivo);
;
// js/components/profile-name.js
(function(B){
 let showing=false;
 B.ensureProfileName=async function(){
  const {data}=await B.supabase.auth.getSession();const user=data?.session?.user;if(!user||showing)return;
  const m=user.user_metadata||{};if(m.username||m.full_name||m.name)return;
  if(!user.identities?.some(i=>i.provider==='google')&&user.app_metadata?.provider!=='google')return;
  const key='bv_name_'+user.id;if(localStorage.getItem(key)){B.AuthStore.set({...B.AuthStore.get(),name:localStorage.getItem(key)});return;}
  showing=true;const dialog=document.createElement('dialog');dialog.className='profile-name-dialog';dialog.innerHTML='<form><button type="button" class="modal-close" aria-label="Close name prompt">×</button><h2>What should we call you?</h2><p>Google did not provide your name. Enter up to 12 characters.</p><label>Your name<input name="name" maxlength="12" required autocomplete="given-name"></label><button class="btn btn-primary" type="submit">Save name</button><p class="fine-print">If you close this, we will use bookivouser.</p></form>';document.body.append(dialog);
  let saving=false;async function save(name){if(saving)return;saving=true;localStorage.setItem(key,name);B.AuthStore.set({...B.AuthStore.get(),name});dialog.close();dialog.remove();showing=false;const {error}=await B.supabase.auth.updateUser({data:{username:name}});B.Toast.show(error?'Name saved on this device. Try again later to sync it.':'Name saved successfully',error?'error':'success');}
  dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const name=dialog.querySelector('input').value.trim();if(!name)return;save(name.slice(0,12));};dialog.querySelector('.modal-close').onclick=()=>save('bookivouser');dialog.oncancel=e=>{e.preventDefault();save('bookivouser');};dialog.showModal();
 };
})(window.Bookivo);
;
